        r, c = q.popleft()
        for nr, nc in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)):
            if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] != wall and (nr,nc) not in outside:
                outside.add((nr,nc)); q.append((nr,nc))
